"""Strict check of gradle/verification-metadata.xml.

Usage:
  python3 -I check-verification-metadata.py FILE              structure only
  python3 -I check-verification-metadata.py FILE --base BASE  structure, plus FILE may only add or
                                                             remove checksums compared with BASE

The structure check accepts exactly what gradle/update-verification-metadata.sh writes: the
<configuration> block and <component>/<artifact> entries with one plain <sha256 value origin>
each. No DOCTYPE or entities, no comments or processing instructions, no PGP entries, no
<also-trust>, no per-artifact <ignored-keys>, no duplicates.

With --base (the Dependabot workflow): the <configuration> block must be identical, and every
artifact that exists in both files must keep its checksum. A new version adds new entries; it can
never replace the checksum of a version that was already verified.

Only the Python standard library is used. Exit code 0 means accepted.
"""

import re
import sys
import xml.etree.ElementTree as ET

NS = "{https://schema.gradle.org/dependency-verification}"
MAX_BYTES = 5_000_000
SHA256 = re.compile(r"^[0-9a-f]{64}$")
ORIGINS = {"Generated by Gradle", "Generated by gradle/update-verification-metadata.sh"}
HEADER = '<?xml version="1.0" encoding="UTF-8"?>'


class Rejected(Exception):
    pass


def load(path):
    with open(path, "rb") as fh:
        raw = fh.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise Rejected(f"{path}: larger than {MAX_BYTES} bytes")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise Rejected(f"{path}: not UTF-8 ({exc})") from None
    text = text.replace("\r\n", "\n")
    if not text.startswith(HEADER + "\n"):
        raise Rejected(f"{path}: first line must be {HEADER}")
    body = text[len(HEADER):]
    for token in ("<!", "<?", "&"):
        if token in body:
            raise Rejected(f"{path}: contains {token!r} (DOCTYPE, entity, comment, CDATA or processing instruction)")
    try:
        root = ET.fromstring(body)
    except ET.ParseError as exc:
        raise Rejected(f"{path}: not well-formed XML ({exc})") from None
    return root


def only(elem, attrs, what):
    extra = set(elem.attrib) - set(attrs)
    missing = [a for a in attrs if a not in elem.attrib and attrs[a]]
    if extra or missing:
        raise Rejected(f"{what}: unexpected attributes {sorted(extra)} / missing {missing}")
    if elem.text and elem.text.strip():
        raise Rejected(f"{what}: unexpected text")


def check(root, path):
    if root.tag != NS + "verification-metadata":
        raise Rejected(f"{path}: root element is not Gradle verification metadata")
    children = list(root)
    if [c.tag for c in children] != [NS + "configuration", NS + "components"]:
        raise Rejected(f"{path}: root must hold exactly <configuration> and <components>")
    config, components = children
    entries = {}
    for comp in components:
        if comp.tag != NS + "component":
            raise Rejected(f"{path}: unexpected element {comp.tag} in <components>")
        only(comp, {"group": True, "name": True, "version": True}, f"{path}: component")
        gav = (comp.get("group"), comp.get("name"), comp.get("version"))
        if not list(comp):
            raise Rejected(f"{path}: component {':'.join(gav)} has no artifacts")
        for art in comp:
            if art.tag != NS + "artifact":
                raise Rejected(f"{path}: {':'.join(gav)}: only <artifact> is allowed, got {art.tag}")
            only(art, {"name": True}, f"{path}: {':'.join(gav)} artifact")
            key = gav + (art.get("name"),)
            sums = list(art)
            if len(sums) != 1 or sums[0].tag != NS + "sha256":
                raise Rejected(f"{path}: {':'.join(key)} must hold exactly one <sha256> (no PGP, no ignored keys)")
            sha = sums[0]
            only(sha, {"value": True, "origin": False}, f"{path}: {':'.join(key)} sha256")
            if list(sha):
                raise Rejected(f"{path}: {':'.join(key)}: <also-trust> or other children are not allowed")
            if not SHA256.match(sha.get("value")):
                raise Rejected(f"{path}: {':'.join(key)}: invalid SHA-256 value")
            if sha.get("origin", "Generated by Gradle") not in ORIGINS:
                raise Rejected(f"{path}: {':'.join(key)}: unexpected origin")
            if key in entries:
                raise Rejected(f"{path}: {':'.join(key)} is listed twice")
            entries[key] = sha.get("value")
    return config, entries


def main(argv):
    if len(argv) not in (2, 4) or (len(argv) == 4 and argv[2] != "--base"):
        print(__doc__, file=sys.stderr)
        return 2
    path = argv[1]
    try:
        config, entries = check(load(path), path)
        if len(argv) == 4:
            base_config, base_entries = check(load(argv[3]), argv[3])
            if ET.canonicalize(ET.tostring(config)) != ET.canonicalize(ET.tostring(base_config)):
                raise Rejected("the <configuration> block changed; only checksums may change")
            changed = [k for k in entries.keys() & base_entries.keys() if entries[k] != base_entries[k]]
            if changed:
                listed = ", ".join(":".join(k) for k in sorted(changed))
                raise Rejected(f"checksums of already verified artifacts changed: {listed}")
            added = len(entries.keys() - base_entries.keys())
            removed = len(base_entries.keys() - entries.keys())
            print(f"Accepted: {added} artifacts added, {removed} removed, none changed.")
        else:
            print(f"Accepted: {len(entries)} artifacts with SHA-256.")
    except (Rejected, OSError) as exc:
        print(f"::error::{exc}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
